// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 value, bytes calldata data, address nonOwner) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != c.owner());
        vm.assume(target != address(c));
        vm.deal(nonOwner, 5 ether);
        vm.prank(nonOwner);
        try c.sendMoney(target, value, data) {} catch { return; }
        bool withdrawReverted;
        vm.prank(nonOwner);
        try c.withdraw(0) { withdrawReverted = false; } catch { withdrawReverted = true; }
        assertTrue(withdrawReverted);
    }
}
